function specialValues(matrix: number[][]): number[] {
  const m = matrix.length, n = matrix[0].length, out: number[] = [];
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      const v = matrix[i][j];
      let ok = true;
      for (let k = 0; k < n && ok; k++) if (matrix[i][k] < v) ok = false;
      for (let k = 0; k < m && ok; k++) if (matrix[k][j] > v) ok = false;
      if (ok) out.push(v);
    }
  }
  return out;
}

