class Solution:
    def specialValues(self, matrix: List[List[int]]) -> List[int]:
        out = []
        for i, row in enumerate(matrix):
            for j, v in enumerate(row):
                if v == min(row) and v == max(r[j] for r in matrix):
                    out.append(v)
        return out

