function specialValues(matrix: number[][]): number[] {
  const n = matrix[0].length;
  const colMax = new Array(n).fill(-Infinity);
  for (const row of matrix) for (let j = 0; j < n; j++) colMax[j] = Math.max(colMax[j], row[j]);
  const tops = new Set(colMax);
  const out: number[] = [];
  for (const row of matrix) {
    const low = Math.min(...row);
    if (tops.has(low)) out.push(low);
  }
  return out;
}

